local WORDS = {}
local CURSOR = {}
local function buildDict()
    for L, csv in pairs(DICT_LETTER) do
        local t = {}
        for w in string.gmatch(csv, "([^,]+)") do t[#t + 1] = w end
        WORDS[L] = t
        CURSOR[L] = 1
    end
end
buildDict()
DICT_LETTER = nil

-- state
local used = {} -- used[WORD] = true (own sends + chat-observed)
local answeredKey = nil
local sending = false
local lastSendT = 0
local status = "starting..."
local lastWord = "-"
local lastPrompt = "-"
local lastResult = "-"
local sendAttempts = 0
local sendLog = {}
local function slog(s)
    sendLog[#sendLog + 1] = s
    if #sendLog > 10 then table.remove(sendLog, 1) end
end

local function markUsed(word)
    if type(word) ~= "string" then return end
    local w = string.upper(word)
    if #w < 2 or #w > 15 then return end
    if not string.match(w, "^[A-Z]+$") then return end
    used[w] = true
end

local function pickWord(prefix)
    local L = string.sub(prefix, 1, 1)
    local list = WORDS[L]
    if not list or #list == 0 then return nil end
    local n = #list
    local start = CURSOR[L] or 1
    for k = 0, n - 1 do
        local w = list[((start + k - 1) % n) + 1]
        if string.sub(w, 1, #prefix) == prefix and not used[w] then
            CURSOR[L] = ((start + k) % n) + 1
            return w
        end
    end
    return nil
end

-- ---- UI reads --------------------------------------------------------------
local function readPrompt()
    if not lp then return nil end
    local pg = lp:FindFirstChild("PlayerGui")
    local sg = pg and pg:FindFirstChild("ScreenGui")
    local tb = sg and sg:FindFirstChild("TopBar")
    if not tb then return nil end
    local q = nil
    local parts = {}
    for _, d in ipairs(tb:GetDescendants()) do
        if d.ClassName == "TextLabel" then
            local ok, t = pcall(function() return d.Text end)
            if ok and type(t) == "string" and t ~= "" then
                if d.Name == "QuestionLabel" then
                    q = t
                elseif string.match(t, "^[A-Za-z]+$") and #t <= 3 then
                    local ap = d.AbsolutePosition
                    parts[#parts + 1] = { t = string.upper(t), x = ap and ap.X or 0 }
                end
            end
        end
    end
    if not q or not string.find(string.lower(q), "starting with", 1, true) then return nil end
    if #parts == 0 then return nil end
    table.sort(parts, function(a, b) return a.x < b.x end)
    -- prefer an explicit multi-letter prefix label, else join split singles
    local prefix = nil
    for _, p in ipairs(parts) do
        if #p.t > 1 then prefix = p.t break end
    end
    if not prefix then
        if #parts == 1 then
            prefix = parts[1].t
        else
            local s = {}
            for _, p in ipairs(parts) do
                if #p.t == 1 then s[#s + 1] = p.t end
            end
            if #s == 0 then return nil end
            prefix = table.concat(s)
        end
    end
    if prefix == "" or #prefix > 3 then return nil end
    return { letter = string.sub(prefix, 1, 1), prefix = prefix, q = q }
end

local function chatWindows()
    local cg = game:FindFirstChild("CoreGui")
    if not cg then return nil end
    for _, c in ipairs(cg:GetChildren()) do
        if c.Name == "ExperienceChat" then return c end
    end
    return nil
end

-- my word visible in chat under my name?
local function observeChat()
    local ec = chatWindows()
    if not ec then return end
    local me = lp and lp.Name or ""
    for _, d in ipairs(ec:GetDescendants()) do
        if d.ClassName == "TextLabel" and d.Name == "BodyText" then
            local ok, t = pcall(function() return d.Text end)
            if ok and type(t) == "string" then
                local w = string.match(t, "^%s*([A-Za-z]+)%s*$")
                if w and #w >= 2 and #w <= 15 then markUsed(w) end
            end
        end
    end
end

local function chatHasMine(word)
    if not lp then return false end
    local ec = chatWindows()
    if not ec then return false end
    local want = string.lower(word)
    local desc = ec:GetDescendants()
    for i, d in ipairs(desc) do
        if d.ClassName == "TextLabel" and d.Name == "BodyText" then
            local ok, t = pcall(function() return d.Text end)
            if ok and type(t) == "string" and string.lower(t) == want then
                return true
            end
        end
        if i > 600 then break end
    end
    return false
end

local function sendWord(word, prefix)
    sending = true
    sendAttempts = sendAttempts + 1
    task.spawn(function()
        local done = function(s)
            status = s
            lastResult = s
            sending = false
        end
        local alive = function() return _G.__SPRINT_GEN == MY_GEN end
        if not alive() then sending = false return end
        slog("esc")
        pcall(function() keypress(K_ESC) end)
        task.wait(0.25)
        if not alive() then sending = false return end
        slog("slash")
        pcall(function() keypress(K_SLASH) end)
        task.wait(0.6)
        if not alive() then sending = false return end
        local p = readPrompt()
        if not p or p.prefix ~= prefix then
            pcall(function() keypress(K_ESC) end)
            slog("abort-moved")
            done("prompt moved, aborted")
            return
        end
        slog("type:" .. #word)
        for i = 1, #word do
            if not alive() then sending = false return end
            pcall(function() keypress(string.byte(word, i)) end)
            task.wait(0.07)
        end
        task.wait(0.25)
        if not alive() then sending = false return end
        slog("enter")
        pcall(function() keypress(K_ENTER) end)
        local t0 = tick()
        local ok = false
        while tick() - t0 < 4 do
            if not alive() then sending = false return end
            if chatHasMine(word) then ok = true break end
            task.wait(0.3)
        end
        markUsed(word)
        if ok then
            lastSendT = tick()
            answeredKey = prefix
            slog("verified")
            done("sent " .. word)
            print("[Sprint] sent: " .. word)
        else
            pcall(function() keypress(K_ESC) end)
            answeredKey = prefix
            slog("miss")
            done("unverified: " .. word)
            print("[Sprint] unverified: " .. word)
        end
    end)
end

-- ---- overlay ---------------------------------------------------------------
local panelBg = Drawing.new("Square")
panelBg.Filled = true
panelBg.Color = Color3.fromRGB(13, 20, 32)
panelBg.Transparency = 0.25
panelBg.Visible = false
local panelTitle = Drawing.new("Text")
panelTitle.Size = 15
panelTitle.Font = 11
panelTitle.Color = Color3.fromRGB(240, 244, 248)
panelTitle.Outline = true
panelTitle.Visible = false
local panelRows = {}
for i = 1, 5 do
    local t = Drawing.new("Text")
    t.Size = 13
    t.Font = 1
    t.Color = Color3.fromRGB(203, 213, 225)
    t.Outline = true
    t.Visible = false
    panelRows[i] = t
end
local function hidePanel()
    panelBg.Visible = false
    panelTitle.Visible = false
    for _, r in ipairs(panelRows) do r.Visible = false end
end

local view = { line1 = "...", line2 = "", solveTxt = "OFF" }

_G.__SprintState = function()
    return "solve=" .. tostring(SOLVE) .. " prompt=" .. lastPrompt
        .. " word=" .. lastWord .. " status=" .. status
        .. " lastResult=" .. lastResult .. " attempts=" .. sendAttempts
        .. " slog=" .. table.concat(sendLog, "|")
        .. " loops=" .. HEALTH.loops .. " renders=" .. HEALTH.renders
        .. " keys=" .. HEALTH.keys .. " err=" .. HEALTH.err
        .. " gen=" .. tostring(_G.__SPRINT_GEN)
end

-- ---- main loop -------------------------------------------------------------
task.spawn(function()
    while running do
        if _G.__SPRINT_GEN ~= MY_GEN then break end
        HEALTH.loops = HEALTH.loops + 1
        local okLoop, errLoop = pcall(function()
            if not ensureServices() then task.wait(1.0) return end
            local p = readPrompt()
            if p then
                lastPrompt = p.prefix
                observeChat()
                if SOLVE and not sending and answeredKey ~= p.prefix
                    and tick() - lastSendT > 3.5 then
                    local w = pickWord(p.prefix)
                    if w then
                        lastWord = w
                        status = "answering " .. w .. "..."
                        sendWord(w, p.prefix)
                    else
                        status = "no fresh word for " .. p.prefix
                    end
                elseif not SOLVE then
                    status = "armed OFF (F6)"
                elseif sending then
                    status = status
                elseif answeredKey == p.prefix then
                    status = "answered " .. p.prefix .. ", waiting next"
                end
            else
                if answeredKey ~= nil then answeredKey = nil end
                lastPrompt = "-"
                status = "waiting for prompt..."
            end
            view.line1 = lastPrompt .. " -> " .. lastWord
            view.line2 = status
            view.solveTxt = SOLVE and "ON" or "OFF"
            task.wait(0.5)
        end)
        if not okLoop then
            HEALTH.err = tostring(errLoop):sub(1, 100)
            print("[Sprint] loop error: " .. tostring(errLoop))
            task.wait(0.5)
        end
    end
end)

-- ---- renderer --------------------------------------------------------------
task.spawn(function()
    while running do
        if _G.__SPRINT_GEN ~= MY_GEN then break end
        HEALTH.renders = HEALTH.renders + 1
        if not VISIBLE then
            hidePanel()
        else
            local vpx, vpy = 1600, 900
            local ws = workspace
            local cam = ws and ws.CurrentCamera
            local vs = cam and cam.ViewportSize
            if vs and vs.X and vs.X > 100 then vpx = vs.X end
            if vs and vs.Y and vs.Y > 100 then vpy = vs.Y end
            local px, py = vpx - 264, 84
            panelBg.Position = Vector2.new(px, py)
            panelTitle.Text = "Sprint [" .. view.solveTxt .. "]"
            panelTitle.Position = Vector2.new(px + 10, py + 6)
            panelTitle.Visible = true
            local rows
            if COMPACT then
                panelBg.Size = Vector2.new(264, 56)
                panelBg.Visible = true
                rows = { view.line1, view.line2 }
            else
                panelBg.Size = Vector2.new(264, 100)
                panelBg.Visible = true
                local uc = 0
                for _ in pairs(used) do uc = uc + 1 end
                rows = { view.line1, view.line2, "used words: " .. uc, "F6 solve F8 full" }
            end
            local y = py + 28
            for i = 1, 5 do
                if rows[i] then
                    panelRows[i].Text = rows[i]
                    panelRows[i].Position = Vector2.new(px + 10, y)
                    panelRows[i].Visible = true
                    y = y + 21
                else
                    panelRows[i].Visible = false
                end
            end
        end
        task.wait(0.08)
    end
    hidePanel()
end)

-- ---- input -----------------------------------------------------------------
task.spawn(function()
    local held = {}
    local keys = { VK.SOLVE, VK.HIDE, VK.RESET, VK.COMPACT }
    while running do
        if _G.__SPRINT_GEN ~= MY_GEN then break end
        for _, code in ipairs(keys) do
            local down = iskeypressed(code)
            if down and not held[code] then
                held[code] = true
                HEALTH.keys = HEALTH.keys + 1
                if code == VK.SOLVE then
                    SOLVE = not SOLVE
                    _G.__SPRINT_SOLVE = SOLVE
                    print("[Sprint] auto-answer: " .. (SOLVE and "ON" or "OFF"))
                    toast("auto-answer " .. (SOLVE and "ON" or "OFF"))
                elseif code == VK.HIDE then
                    VISIBLE = not VISIBLE
                    print("[Sprint] overlay: " .. tostring(VISIBLE))
                elseif code == VK.RESET then
                    used = {}
                    answeredKey = nil
                    print("[Sprint] memory reset")
                    toast("memory reset")
                elseif code == VK.COMPACT then
                    COMPACT = not COMPACT
                    print("[Sprint] compact: " .. tostring(COMPACT))
                end
            elseif not down then
                held[code] = false
            end
        end
        task.wait(0.08)
    end
end)

print("[Sprint] Word Sprint v1 loaded")
print("[Sprint] Keys: F6 answer | F7 hide | F4 reset | F8 compact")
